// Rebuilds `shares` from PIPELINE for every date STRICTLY BEFORE today.
// Today is excluded on purpose: the live per-send recording added on 30 Sep
// already owns today, and backfilling it would double-count. No deletion is
// performed, so this is an insert-only one-off, not a re-runnable sync.
const vr = $('GET pipeline').first().json.valueRanges[0].values;
const h = vr[0];
const rows = vr.slice(1).map(function (r) { var o = {}; h.forEach(function (k, i) { o[k] = r[i] === undefined ? '' : r[i]; }); return o; });
const nz = function (s) { return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, ''); };
const sMap = {}; for (const s of ($('GET startup ids').first().json.body || [])) { sMap[nz(s.name)] = s.id; }
const iMap = {}; for (const i of ($('GET investor ids').first().json.body || [])) { iMap[nz(i.name)] = i.id; }
const ISO = /^\d{4}-\d{2}-\d{2}$/;
const today = new Date(Date.now() + 19800000).toISOString().slice(0, 10);
const ts = function (d) { return d + 'T09:00:00+05:30'; };
const mt = function (raw) {
  raw = String(raw || '');
  if (/stage\s+(?:one\s+step\s+)?off/i.test(raw)) return 'stage_off';
  if (/^\s*exact\s+match/i.test(raw)) return 'strict';
  if (/sector\s*\+\s*cheque\s+match/i.test(raw)) return 'sector_only';
  if (/minimum\s+cheque|fails\s+cheque/i.test(raw)) return 'below_min_cheque';
  return null;
};
const out = []; const miss = { s: {}, i: {} }; let skipped = 0; let excludedToday = 0;
for (const r of rows) {
  const sid = sMap[nz(r.startup)]; const iid = iMap[nz(r.investor)];
  if (!sid) { miss.s[String(r.startup)] = 1; }
  if (!iid) { miss.i[String(r.investor)] = 1; }
  if (!sid || !iid) { skipped++; continue; }
  const type = mt(r.match_type); const mb = String(r.owner || '').trim() || null;
  const add = function (d, fu, no) {
    d = String(d == null ? '' : d).trim();
    if (!ISO.test(d)) { return; }
    if (d >= today) { excludedToday++; return; }
    out.push({ startup_id: sid, investor_id: iid, sent_at: ts(d), mailbox: mb, type: type, is_followup: fu, followup_no: no });
  };
  if (String(r.deal_shared || '').trim().toLowerCase() === 'yes') { add(r.date_shared, false, null); }
  add(r.fu1_date, true, 1); add(r.fu2_date, true, 2); add(r.fu3_date, true, 3);
}
const CH = 800; const chunks = [];
for (let i = 0; i < out.length; i += CH) { chunks.push({ json: { rows: out.slice(i, i + CH), total: out.length, skipped: skipped, excluded_today: excludedToday, missing_startups: Object.keys(miss.s), missing_investors: Object.keys(miss.i) } }); }
return chunks.length ? chunks : [{ json: { rows: [], total: 0, skipped: skipped, excluded_today: excludedToday, missing_startups: [], missing_investors: [] } }];

const b = $('Build shares').first().json;
const items = $input.all();
const res = items.map(function (i) { return i.json.statusCode; });
const bad = items.filter(function (i) { return !(i.json.statusCode >= 200 && i.json.statusCode < 300); });
return [{ json: {
  share_rows_built: b.total,
  chunks: res.length,
  chunk_statuses: res,
  failed_chunks: bad.length,
  errors: bad.map(function (i) { return JSON.stringify(i.json.body).slice(0, 200); }).slice(0, 3),
  excluded_today: b.excluded_today,
  pipeline_rows_skipped_no_id_match: b.skipped,
  missing_startups: b.missing_startups,
  missing_investors: b.missing_investors
} }];
